from itertools import combinations
lines=[{'b', 'a'}, {'c', 'b'}, {'d', 'c'}, {'a', 'd'}, {'m2', 'm3', 'm1'}, {'m5', 'm4', 'm6'}, {'m4', 'm1'}, {'m5', 'm2'}, {'m3', 'm6'}, {'m5', 'm1'}, {'m5', 'm3'}, {'p', 'q'}, {'r', 'q'}, {'s', 'r'}, {'p', 's'}, {'o', 'q'}, {'p', 'o'}]
pts=set().union(*lines)
extra=4+4  # corner triangles of the two inscribed-diamond squares (each corner closed by square sides)
def on(a,b): return any(a in l and b in l for l in lines)
def col(a,b,c): return any({a,b,c}<=l for l in lines)
n=extra+len([c for c in combinations(sorted(pts),3) if on(c[0],c[1]) and on(c[1],c[2]) and on(c[0],c[2]) and not col(*c)])
opts={'A': 11, 'B': 9, 'C': 12, 'D': 14}
assert n==opts['D']
for k,v in opts.items():
    if k!='D': assert n!=v

