import itertools
views=[('A','B','C'),('C','B','E'),('F','C','E')]
adj=set()
for v in views:
    for a,b in itertools.combinations(v,2): adj.add(frozenset((a,b)))
L='ABCDEF'; sols=set()
def pairings(s):
    if not s: yield []; return
    a=s[0]
    for b in s[1:]:
        rest=[x for x in s if x not in (a,b)]
        for p in pairings(rest): yield [(a,b)]+p
for p in pairings(list(L)):
    if all(frozenset(x) not in adj for x in p):
        for x,y in p:
            if x=='A': sols.add(y)
            if y=='A': sols.add(x)
assert sols=={'E'}
r='E'; opts={'A':'D','B':'C','C':'E','D':'F'}
assert r==opts['C']
for k in 'ABD': assert r!=opts[k]

from itertools import permutations
faces=['A', 'B', 'C', 'D', 'E', 'F']
views=[['A', 'B', 'C'], ['C', 'B', 'E'], ['F', 'C', 'E']]
adj=set()
for v in views:
    for a in v:
        for b in v:
            if a!=b: adj.add(frozenset((a,b)))
sols=set()
for p in permutations(faces):
    pairs=[frozenset((p[0],p[1])),frozenset((p[2],p[3])),frozenset((p[4],p[5]))]
    if any(q in adj for q in pairs): continue
    for q in pairs:
        if 'A' in q: sols.add(next(iter(q-{'A'})))
assert len(sols)==1
ans=sols.pop()
opts={'A': 'D', 'B': 'C', 'C': 'E', 'D': 'F'}
assert ans==opts['C']
for k,v in opts.items():
    if k!='C': assert ans!=v

